package com.ruoyi.framework.audit;
import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import com.ruoyi.metal.security.FactoryScope;import com.alibaba.fastjson2.JSON;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class LogQueryCaptureIntegrityTest{
 @Test void storedRequestCollectionIsNotSilentlyShortenedDuringRead(){var j=mock(JdbcTemplate.class);var scope=mock(FactoryScope.class);when(scope.currentFactory()).thenReturn(null);var input=Map.of("body",Map.of("items",Collections.nCopies(101,"x"),"password","sentinel"));when(j.queryForList(anyString(),any(Object[].class))).thenReturn(List.of(new LinkedHashMap<>(Map.of("oper_param",JSON.toJSONString(input)))));var row=new LogQueryService(j,scope).detail("operation",1L);var request=JSON.parseObject(row.get("operParam").toString());assertEquals(101,request.getJSONObject("body").getJSONArray("items").size());assertFalse(row.toString().contains("sentinel"));}
 @Test void validatedIdentifiersAreNotMistakenForPhoneNumbers(){var j=mock(JdbcTemplate.class);var scope=mock(FactoryScope.class);when(scope.currentFactory()).thenReturn(null);String trace="aaaaaaaaaa13912345678aaaaaaaaaaa",event="aaaaaaaa-aaaa-aaaa-aaaa-a13912345678";when(j.queryForList(anyString(),any(Object[].class))).thenReturn(List.of(new LinkedHashMap<>(Map.of("trace_id",trace,"event_id",event,"actor_name","17123456789","oper_id",13912345678L))));var row=new LogQueryService(j,scope).detail("operation",1L);assertEquals(trace,row.get("traceId"));assertEquals(event,row.get("eventId"));assertEquals("13912345678",row.get("operId"));assertEquals("171****6789",row.get("actorName"));}
}
